    armyPanel:$('[data-role=armyPanel]'),armySummary:$('[data-testid=army-summary]'),armyBody:$('[data-role=armyBody]'),armyList:$('[data-role=armyList]'),armyLogo:$('[data-role=armyLogo]'),armyGroup:$('[data-role=armyGroup]'),armyGroupName:$('[data-role=armyGroupName]'),armyGroupMeta:$('[data-role=armyGroupMeta]'),armyPrev:$('[data-testid=army-page-prev]'),armyNext:$('[data-testid=army-page-next]'),trainBtn:$('[data-action=train]'),
    distillPanel:$('[data-role=distillPanel]'),distillSummary:$('[data-testid=distill-summary]'),distillBody:$('[data-role=distillBody]'),distillBtn:$('[data-action=distill]'),
    backdrop:$('[data-role=drawerBackdrop]'),drawerTabs:$('[data-role=drawerTabs]'),helpText:$('[data-role=helpText]'),logList:$('[data-role=logList]'),logPrev:$('[data-log-page=prev]'),logNext:$('[data-log-page=next]'),
