    ctx.strokeStyle='#ffffff12';ctx.lineWidth=1;
    for(let x=-100;x<W+200;x+=90){ctx.beginPath();ctx.moveTo(W*.5+(x-W*.5)*.75,groundY+1);ctx.lineTo(x,H);ctx.stroke();}
    const ev=currentEvent(s);
    ctx.textAlign='left';ctx.textBaseline='alphabetic';
    // 左侧：手机/窄屏最多 3 个角色，避免和敌人卡互相遮挡
    const owned=ROSTER.enabledVendors.filter(v=>ROSTER.models.some(m=>m.vendor===v&&s.models.includes(m.id)));
    const compactCanvas=W<520;
    // 同屏尽量多放：宽屏 10 位、620 级 6 位、手机 4–5 位；其余在军团页查看
    const maxChars=compactCanvas?(W<430?4:5):(W<760?6:Math.max(1,ROSTER.maxVisibleCharacters||10));
    const byVendor=vendorPowers(s);
    const sortedOwned=[...owned].sort((a,b)=>compare(byVendor[b]||amount(0),byVendor[a]||amount(0)));
    const starterVendor=ROSTER.enabledVendors[0];
    const pinned=sortedOwned.includes(starterVendor)?[starterVendor,...sortedOwned.filter(v=>v!==starterVendor)]:sortedOwned;
    const visibleOwned=pinned.slice(0,maxChars);
    // 角色占满整个战场宽度；敌人状态压缩为顶部一条窄状态条，给模型名留出空间
    const slot=Math.max(24,Math.min(150,(W-12)/Math.max(1,visibleOwned.length)));
    const charH=Math.max(40,Math.min(H*0.64,groundY-14));
