      const accent=restricted?'#B0ACA0':(VENDOR_TEXT[id]||VENDOR_COLORS[id]);
      chars.push({id,x:charX,y:groundY,targetH,restricted});
      ctx.fillStyle='#00000066';ctx.beginPath();ctx.ellipse(x,groundY-2,Math.max(8,charH*.20),Math.max(2,charH*.05),0,0,Math.PI*2);ctx.fill();
