        const modelName=latest?latest.name:'';
        const modelSize=fitFontSize(modelName,slot-6,'400',compactCanvas?9:10,6.2);
        ctx.globalAlpha=.86;ctx.font=`${modelSize}px 'PingFang SC','Heiti SC',system-ui,sans-serif`;
