    const boss=s.stage%10===0;
    const statusText=`${boss?'FINAL_v9.md':'TODO.md'} · 剩余 ${Math.round(hp*100)}% · STAGE ${s.stage}`;
    ctx.save();ctx.textAlign='center';ctx.font="600 9px 'PingFang SC','Heiti SC',system-ui,sans-serif";
    const statusW=Math.min(W-20,Math.ceil(ctx.measureText(statusText).width)+16),statusH=20;
    const statusX=Math.round(W-statusW-8),statusY=8;
    ctx.fillStyle=boss?'#221A1A':'#1B1E26';ctx.fillRect(statusX,statusY,statusW,statusH);
    ctx.strokeStyle=boss?'#E74438':'#4D6BFE';ctx.lineWidth=1;ctx.strokeRect(statusX+.5,statusY+.5,statusW-1,statusH-1);
    ctx.fillStyle=boss?'#FF8A7A':'#DCE3FF';ctx.fillText(statusText,statusX+statusW/2,statusY+14);
    ctx.restore();
    // 敌人工作量条：让“还剩多少”一眼可读
